insert into settings(key, value, updated_at) values ('icp_profiles', '{"profiles": [{"name": "The new business that has to look established", "status": "draft", "who": "Someone who just formed an LLC or left a job to go solo \u2014 a trade, a practice, a consultancy. They have a phone number and a logo someone''s cousin made.", "pains": ["Looking new costs them money in the first conversation", "Competitors with worse work win on looking professional", "No time to learn website builders, and it shows when they try"], "buying_triggers": ["Just registered the business", "First real client asked for their website and they winced", "A competitor launched a site that looks expensive"], "what_we_lead_with": "Looking established from day one changes what people are willing to pay you. Logo and site together, live in about a month.", "maps_to_service": "Starter Package ($4,500)"}, {"name": "The business the simple website has outgrown", "status": "draft", "who": "An established small business \u2014 2 to 20 people \u2014 whose site is a brochure while staff quote, book, and answer the same questions by hand every day.", "pains": ["The website describes the business but does no work for it", "Quoting and booking eat hours that should be billable", "Enquiries land in one inbox and go cold on busy weeks"], "buying_triggers": ["Hired someone and realised half the job is copy-paste admin", "Lost a lead they never replied to", "A slow season made them look hard at where enquiries come from"], "what_we_lead_with": "The website should take work off your desk \u2014 quoting, booking, and answering the same questions without you in the loop.", "maps_to_service": "Growth / Professional Package ($9,500) or Custom Business Site ($8,500)"}, {"name": "The business paying monthly for software that half fits", "status": "draft", "who": "An operation that runs on spreadsheets plus two or three per-user SaaS subscriptions, none of which match how they actually work.", "pains": ["Per-user fees climb every time they hire", "Information is re-typed between systems that do not talk", "The tool forces their process to bend to it, not the reverse"], "buying_triggers": ["The subscription renewal made someone do the maths", "An error from double-keying cost real money", "The vendor discontinued or repriced a feature they depend on"], "what_we_lead_with": "Own the system instead of renting it \u2014 built around how you already work, with no per-user fee that grows when you do.", "maps_to_service": "Complex Web App / Portal ($18,500\u2013$22,000) or Enterprise ($22,500)"}, {"name": "The business whose brand looks homemade", "status": "draft", "who": "A business that is good at what it does and looks like it is not \u2014 template logo, inconsistent colours, social graphics that change style weekly.", "pains": ["The work is premium; the brand reads budget", "Every printed thing looks slightly different", "They cannot hand marketing to anyone because nothing is written down"], "buying_triggers": ["Saw their logo next to competitors'' at an event and flinched", "A printer or sign maker asked for files they do not have", "About to spend on ads and realised the brand is not ready to be seen"], "what_we_lead_with": "An original mark that is legally and visually yours, in every file anyone will ever ask for.", "maps_to_service": "Logo Suite ($2,500) or Full Brand Identity ($6,500)"}]}'::jsonb, now()) on conflict (key) do update set value=excluded.value, updated_at=now();
insert into settings(key, value, updated_at) values ('services', '{"services": [{"title": "Single-Page / Landing Page Site", "price": "$3,800", "is_for": "one strong offer that needs one strong page", "outcome": "a page built to turn visitors into enquiries, with a form that emails the owner instantly"}, {"title": "Custom 3\u20137 Page Business Site", "price": "$8,500", "is_for": "a small business that needs its whole story online", "outcome": "a site a stranger can arrive at, understand the business, and get in touch \u2014 editable by the owner without calling us"}, {"title": "Complex Web App / Multi-Page Portal", "price": "$18,500\u2013$22,000", "is_for": "a business whose process deserves its own software", "outcome": "secure client sign-in, one dashboard instead of four systems, connected to the tools they already use"}, {"title": "Boutique Logo Design Suite", "price": "$2,500", "is_for": "a business that needs a real mark, not a template", "outcome": "an original logo drawn from scratch, in every version and file format a printer or sign maker will ever ask for"}, {"title": "Full Brand Identity Package", "price": "$6,500", "is_for": "a business ready to look like one company everywhere", "outcome": "positioning first, then a complete logo system, colours, fonts, social kit, and a written guide anyone can follow"}, {"title": "Starter Package", "price": "$4,500", "is_for": "a new business launching", "outcome": "logo and 3\u20135 page site together \u2014 looking established from day one"}, {"title": "Growth / Professional Package", "price": "$9,500", "is_for": "a business the simple site has outgrown", "outcome": "full brand kit plus a 6\u201312 page site with working tools: price calculator, online booking, client login"}, {"title": "Enterprise / Custom Application", "price": "$22,500+", "is_for": "software the business depends on", "outcome": "a complete custom platform built end to end, connected to their systems, owned not rented"}, {"title": "Hourly Design & Engineering", "price": "$150/hr", "is_for": "changes and advice after launch", "outcome": "tracked, itemised hours \u2014 no retainer, no project overhead for small work"}, {"title": "Design Consultation", "price": "quoted per engagement", "is_for": "work that fits no standard package", "outcome": "scoped and priced for what it actually involves"}]}'::jsonb, now()) on conflict (key) do update set value=excluded.value, updated_at=now();
insert into settings(key, value, updated_at) values ('proof_points', '{"points": ["We designed, built, and launched All in 1 Events \u2014 a complete site for an event-services company, live in production", "meridianinterface.com is built in-house: React, a licensed cinematic video hero, and a client booking portal \u2014 the studio''s own work is its portfolio", "We run our own always-on AI marketing system \u2014 CRM, content drafting, and lead follow-up on autopilot with human approval \u2014 the same class of system we build for clients", "Our client portal keeps invoices in a real database behind server-side authentication \u2014 we use what we sell", "Our rates are published openly with what each price includes and excludes \u2014 clients see the numbers before they ever talk to us"]}'::jsonb, now()) on conflict (key) do update set value=excluded.value, updated_at=now();
insert into settings(key, value, updated_at) values ('content_rules', '{"always": ["Write in plain words a busy owner reads in one pass \u2014 the reader''s business is the subject, not ours", "Make one concrete claim per piece and support it with something real (a price, a shipped project, a specific mechanism)", "Name real prices plainly when relevant \u2014 price transparency is a differentiator, use it", "End with one specific, low-pressure invitation (a question to reply to, a page to see) \u2014 not a generic ''let''s talk''", "Say what is NOT included when discussing a service \u2014 honesty about scope is part of the brand"], "never": ["Invent clients, projects, statistics, or testimonials \u2014 only the proof points listed are true", "Promise timelines shorter than the published catalogue, or guaranteed Google rankings", "Use filler marketing words: unlock, elevate, empower, seamless, cutting-edge, game-changing, revolutionize", "Disparage named competitors or manufacture urgency (fake deadlines, fake scarcity)", "Claim certifications, awards, or team size that have not been stated by the owner"]}'::jsonb, now()) on conflict (key) do update set value=excluded.value, updated_at=now();
insert into settings(key, value, updated_at) values ('business_profile', '{"name": "Meridian Interface", "industry": "web & software development studio", "voice": "confident, clear, and helpful; speaks plainly to busy small-business owners, no jargon", "website": "www.meridianinterface.com", "location": "Houston, Texas", "service_area": "remote-friendly \u2014 clients anywhere in the US; Houston roots", "timezone": "America/Chicago"}'::jsonb, now()) on conflict (key) do update set value=excluded.value, updated_at=now();
-- The shared context layer: everything every agent knows about the business,
-- in five settings rows read by _shared/context.ts. Editing these rows changes
-- what the agents write on their next run — no redeploy needed.
--
-- icp_profiles.status='draft' marks profiles inferred from the pricing
-- catalogue rather than confirmed by the owner; the prompt renderer labels
-- them so content can lean on them without treating them as settled fact.
